CSV_DEFAULT = ROOT / "uploads" / "phuong_an_sap_nhap_toan_tinh_v13.csv"
GUIDE = ROOT / "HUONG_DAN_V13_SAP_NHAP_TOAN_TINH.txt"
EXPORTS = ROOT / "exports"

PAYLOADS = {
    SERVICE: '',
    ROUTER: '',
    MAIN_TEMPLATE: '',
    PLANS_TEMPLATE: '',
    IMPORTER: '',
}

CSV_HEADER = 'document_code,document_title,document_date,school_year_code,commune,level_code,source_schools,target_school,note\n'
GUIDE_TEXT = 'V13 - SÁP NHẬP TRƯỜNG TOÀN TỈNH THEO VĂN BẢN CHÍNH THỨC\n===========================================================\n\nNGUYÊN TẮC\n----------\n1. Không ghép nguồn/đích tự do.\n2. Chỉ phương án được nạp từ văn bản chính thức mới xuất hiện.\n3. Chỉ status=APPROVED mới được thực hiện.\n4. COMPLETED chỉ xem, không chạy lại.\n5. Dữ liệu các năm trước thời điểm sáp nhập giữ nguyên.\n6. Dữ liệu năm hiện hành và năm tương lai phải theo trường đích.\n7. Log/audit giữ tại đơn vị phát sinh.\n8. Xã/phường dùng ô gõ tìm nhanh.\n\nFILE CSV CHÍNH THỨC\n-------------------\nC:\\PhoCap\\uploads\\phuong_an_sap_nhap_toan_tinh_v13.csv\n\nCột:\n- document_code\n- document_title\n- document_date\n- school_year_code\n- commune\n- level_code\n- source_schools\n- target_school\n- note\n\nsource_schools: nhiều trường, ngăn bằng dấu ;\ncommune/trường: có thể dùng mã hoặc tên chính xác.\n\nKIỂM TRA CSV\n------------\ncd C:\\PhoCap\n.\\.venv\\Scripts\\python.exe .\\tools\\import_official_school_merger_plans_v13.py\n\nGHI THẬT SAU KHI DRY-RUN PASS\n-----------------------------\ncd C:\\PhoCap\n.\\.venv\\Scripts\\python.exe .\\tools\\import_official_school_merger_plans_v13.py `\n  --apply `\n  --confirm "NAP PHUONG AN SAP NHAP TOAN TINH"\n\nLƯU Ý\n-----\nKhông tự lập CSV bằng suy đoán. CSV phải được dựng từ quyết định/phương án chính thức.\nQĐ 3805 Nghi Lộc hiện có được giữ nguyên trạng thái COMPLETED.\n'


def decode(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else ""


def db_state() -> tuple[int, int] | None:
    if not DB_PATH.exists():
        return None
    st = DB_PATH.stat()
    return st.st_size, st.st_mtime_ns


def plan_bytes() -> bytes | None:
    return PLAN_FILE.read_bytes() if PLAN_FILE.exists() else None


def validate_current() -> None:
    required = [SERVICE, ROUTER, MAIN_TEMPLATE, PLANS_TEMPLATE, PLAN_FILE, DB_PATH]
    missing = [str(p) for p in required if not p.exists()]
    if missing:
        raise RuntimeError("Thiếu file nền: " + " | ".join(missing))

    service_text = SERVICE.read_text(encoding="utf-8-sig")
    if (
        "SINGLE_DOCUMENT_LOCK = True" not in service_text
        and "OFFICIAL_REGISTRY_LOCK = True" not in service_text
    ):
        raise RuntimeError(
            "Service sáp nhập không đúng nền QĐ3805/V13; dừng để tránh ghi đè nhầm."
        )

    payload = json.loads(PLAN_FILE.read_text(encoding="utf-8"))
    plans = payload.get("plans")
    if not isinstance(plans, list):
        raise RuntimeError("File phương án hiện tại không có mảng plans.")

    qd = [
        p for p in plans
        if isinstance(p, dict)
        and (
            str(p.get("id") or "").startswith("QD3805-")
            or "3805" in str(p.get("document_code") or "")
        )
    ]
    if len(qd) != 6:
        raise RuntimeError(
            f"QĐ3805 phải còn đúng 6 nhóm trước V13; hiện={len(qd)}."
        )
    bad = [
        str(p.get("id"))
        for p in qd
        if str(p.get("status") or "").upper() != "COMPLETED"
    ]
    if bad:
        raise RuntimeError(
            "6 nhóm QĐ3805 chưa ở trạng thái COMPLETED: " + ", ".join(bad)
        )

    con = sqlite3.connect(str(DB_PATH))
    try:
        integrity = con.execute("PRAGMA integrity_check").fetchone()[0]
        fk = con.execute("PRAGMA foreign_key_check").fetchall()
    finally:
        con.close()

    if integrity != "ok" or fk:
        raise RuntimeError(
            f"Database chưa an toàn: integrity={integrity}, FK={len(fk)}"
        )


def validate_new_files() -> None:
    ast.parse(SERVICE.read_text(encoding="utf-8"))
    ast.parse(ROUTER.read_text(encoding="utf-8"))
    ast.parse(IMPORTER.read_text(encoding="utf-8"))

    py_compile.compile(str(SERVICE), doraise=True)
    py_compile.compile(str(ROUTER), doraise=True)
    py_compile.compile(str(IMPORTER), doraise=True)

    try:
        from jinja2 import Environment
        env = Environment()
        env.parse(MAIN_TEMPLATE.read_text(encoding="utf-8"))
        env.parse(PLANS_TEMPLATE.read_text(encoding="utf-8"))
    except ImportError:
        pass

    service_text = SERVICE.read_text(encoding="utf-8")
    main_text = MAIN_TEMPLATE.read_text(encoding="utf-8")
    plans_text = PLANS_TEMPLATE.read_text(encoding="utf-8")

    checks = {
        "province service": "OFFICIAL_REGISTRY_LOCK = True" in service_text,
        "no single doc filter active": "SINGLE_DOCUMENT_LOCK = False" in service_text,
        "manual mutation blocked": "Sổ phương án sáp nhập toàn tỉnh chỉ được nạp từ văn bản chính thức" in service_text,
        "province title": "Sáp nhập trường toàn tỉnh" in main_text,
        "official registry button": "Danh sách phương án chính thức toàn tỉnh" in main_text,
        "past/future policy": "Dữ liệu năm hiện hành và năm tương lai phải theo trường đích" in main_text,
        "readonly plans": "Không sáp nhập tự do" in plans_text,
        "quick commune": "Gõ từ đầu tên xã/phường" in plans_text,
        "no draft UI": "Lưu phương án NHÁP" not in plans_text,
        "importer installed": IMPORTER.exists(),
    }
    failed = [k for k,v in checks.items() if not v]
    if failed:
        raise RuntimeError("Hậu kiểm V13 chưa đạt: " + ", ".join(failed))


def main() -> int:
    print("=" * 120)
    print("V13 - SÁP NHẬP TRƯỜNG TOÀN TỈNH THEO VĂN BẢN CHÍNH THỨC")
    print("=" * 120)
    print("Cài mã nguồn: CÓ")
    print("Sửa database: KHÔNG")
    print("Sửa file phương án hiện có: KHÔNG")
    print()

    validate_current()

    db_before = db_state()
    plan_before = plan_bytes()

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = EXPORTS / f"backup_v13_sap_nhap_toan_tinh_{stamp}"
    backup.mkdir(parents=True, exist_ok=False)

    tracked = [SERVICE, ROUTER, MAIN_TEMPLATE, PLANS_TEMPLATE]
    created = [IMPORTER, CSV_TEMPLATE, GUIDE]
    for p in tracked:
        dst = backup / p.relative_to(ROOT)
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, dst)

    # Lưu bản sao plan nhưng không sửa plan.
    plan_backup = backup / PLAN_FILE.relative_to(ROOT)
    plan_backup.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(PLAN_FILE, plan_backup)

    try:
        for path, blob in PAYLOADS.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(decode(blob), encoding="utf-8")

        CSV_TEMPLATE.parent.mkdir(parents=True, exist_ok=True)
        CSV_TEMPLATE.write_text(CSV_HEADER, encoding="utf-8-sig")

        # Không ghi đè file dữ liệu chính thức nếu người dùng đã có.
        if not CSV_DEFAULT.exists():
            CSV_DEFAULT.write_text(CSV_HEADER, encoding="utf-8-sig")

        GUIDE.write_text(GUIDE_TEXT, encoding="utf-8")

        validate_new_files()

        if db_before != db_state():
            raise RuntimeError("Database thay đổi ngoài dự kiến trong lúc cài V13.")

        if plan_before != plan_bytes():
            raise RuntimeError("File phương án hiện có đã thay đổi ngoài dự kiến.")

    except Exception:
        for p in tracked:
            src = backup / p.relative_to(ROOT)
            if src.exists():
                p.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, p)

        # Khôi phục plan tuyệt đối.
        if plan_backup.exists():
            shutil.copy2(plan_backup, PLAN_FILE)

        # Xóa file mới nếu V13 thất bại.
        for p in created:
            try:
                if p.exists():
                    p.unlink()
            except Exception:
                pass
        raise

    report = backup / "00_KET_QUA_V13.txt"
    report.write_text(
        "\n".join([
            "V13 - SÁP NHẬP TRƯỜNG TOÀN TỈNH",
            "=" * 80,
            "STATUS=SUCCESS",
            "Database=KHÔNG THAY ĐỔI",
            "Plan JSON hiện có=KHÔNG THAY ĐỔI",
            "QĐ3805=GIỮ NGUYÊN 6 nhóm COMPLETED",
            "UI=toàn tỉnh, xã/phường tìm nhanh",
            "Manual plan mutation=BỊ KHÓA",
            "Plan source=CSV lập từ văn bản chính thức",
            f"Importer={IMPORTER}",
            f"CSV mẫu={CSV_TEMPLATE}",
            f"Backup={backup}",
        ]),
        encoding="utf-8",
    )

    print("CÀI V13 THÀNH CÔNG")
    print(f"Backup: {backup}")
    print("Database: KHÔNG THAY ĐỔI")
    print("QĐ3805: GIỮ NGUYÊN")
    print("Sáp nhập tự do: KHÓA")
    print("Phạm vi: TOÀN TỈNH")
    print(f"Importer chính thức: {IMPORTER}")
    print(f"CSV mẫu: {CSV_TEMPLATE}")
    print()
    print("Khởi động lại phần mềm và mở:")
    print("  1. Danh mục -> 1.3 Công cụ dữ liệu -> 1.3.2 Sáp nhập trường")
    print("  2. Danh sách phương án chính thức toàn tỉnh")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print()
        print("=" * 120)
        print("V13 THẤT BẠI - ĐÃ KHÔI PHỤC SOURCE")
        print("=" * 120)
        print(repr(exc))
        print("Database không thay đổi.")
        raise SystemExit(2)
